cancel_action_item(uuid,text).def:
CREATE OR REPLACE FUNCTION public.cancel_action_item(p_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row public.action_items;
begin
  if not public.is_canmanage() then raise exception 'Not authorized to cancel action items'; end if;
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'A reason is required to cancel an action item';
  end if;
  select * into v_row from public.action_items where id = p_id;
  if not found then raise exception 'Action item not found'; end if;
  if v_row.department_id <> public.my_department_id() then
    raise exception 'Not authorized: belongs to another department';
  end if;
  update public.action_items set
    status = 'cancelled',
    cancelled_at = now(),
    cancelled_by = public.my_member_id(),
    cancel_reason = btrim(p_reason),
    assignee_name = coalesce(
      (select m.name from public.members m where m.id = v_row.assigned_to),
      assignee_name
    )
  where id = p_id;
end; $function$

complete_action_item(uuid).def:
CREATE OR REPLACE FUNCTION public.complete_action_item(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row public.action_items;
begin
  if not public.is_canmanage() then raise exception 'Not authorized to complete action items'; end if;
  select * into v_row from public.action_items where id = p_id;
  if not found then raise exception 'Action item not found'; end if;
  if v_row.department_id <> public.my_department_id() then raise exception 'Not authorized: belongs to another department'; end if;
  update public.action_items set
    status = 'done', completed_at = now(), completed_by = public.my_member_id(),
    assignee_name = coalesce((select m.name from public.members m where m.id = v_row.assigned_to), assignee_name)
  where id = p_id;
end; $function$

is_muted(uuid,text).def:
CREATE OR REPLACE FUNCTION public.is_muted(p_member uuid, p_family text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_enabled boolean;
begin
  IF p_family IS NULL OR p_family NOT IN ('certs','gear','maint','events','tasks','shifts') THEN
    RAISE EXCEPTION 'is_muted: unknown notification family %. A typo here would silently ignore a member''s opt-out.', coalesce(p_family, '<null>');
  END IF;

  select enabled into v_enabled
    from public.notification_prefs
   where member_id = p_member and family = p_family;

  -- ABSENCE MEANS ON, matching the client: a member who has never opened the
  -- preferences screen has no row, and no row is not an opt-out.
  return v_enabled is not null and v_enabled = false;
end;
$function$

notify_action_item_assigned().def:
CREATE OR REPLACE FUNCTION public.notify_action_item_assigned()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_text text;
  v_body text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.assigned_to IS NOT DISTINCT FROM OLD.assigned_to THEN RETURN NULL; END IF;
  IF NEW.department_id IS NULL THEN RETURN NULL; END IF;
  IF coalesce(NEW.status, 'open') <> 'open' THEN RETURN NULL; END IF;
  IF NEW.assigned_to = public.my_member_id() THEN RETURN NULL; END IF;
  IF public.is_muted(NEW.assigned_to, 'tasks') THEN RETURN NULL; END IF;
  v_text := coalesce(nullif(btrim(NEW.text), ''), 'A task has been assigned to you.');
  IF length(v_text) > 120 THEN v_text := left(v_text, 117) || U&'\2026'; END IF;
  v_body := v_text || CASE WHEN NEW.due_date IS NOT NULL THEN ' · due ' || to_char(NEW.due_date, 'Mon DD') ELSE '' END;
  INSERT INTO public.notifications (department_id, member_id, type, title, body, subject_ref, severity)
  VALUES (NEW.department_id, NEW.assigned_to, 'task_assigned', 'New task assigned', v_body, NEW.id::text, 'info')
  ON CONFLICT (member_id, type, subject_ref) DO NOTHING;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'notify_action_item_assigned failed for item %: %', NEW.id, SQLERRM;
  RETURN NULL;
END;
$function$

reopen_action_item(uuid).def:
CREATE OR REPLACE FUNCTION public.reopen_action_item(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row public.action_items; v_resolved timestamptz;
begin
  if not public.is_canmanage() then raise exception 'Not authorized to reopen action items'; end if;
  select * into v_row from public.action_items where id = p_id;
  if not found then raise exception 'Action item not found'; end if;
  if v_row.department_id <> public.my_department_id() then
    raise exception 'Not authorized: belongs to another department';
  end if;
  v_resolved := coalesce(v_row.completed_at, v_row.cancelled_at);
  if v_resolved is not null and (now() - v_resolved) >= interval '14 days' then
    raise exception 'This item was resolved over 14 days ago and is now archived — it can no longer be reopened';
  end if;
  update public.action_items set
    status = 'open',
    completed_at = null, completed_by = null,
    cancelled_at = null, cancelled_by = null, cancel_reason = null
  where id = p_id;
end; $function$

set_fundraiser_shared(uuid,boolean).def:
CREATE OR REPLACE FUNCTION public.set_fundraiser_shared(p_fundraiser_id uuid, p_shared boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- B4C:station_fundraiser — department-scoped leader write of fundraisers.shared_with_station ONLY.
declare
  v_my_dept uuid := public.my_department_id();
begin
  if p_shared is null then raise exception 'Choose shared or not shared'; end if;
  if v_my_dept is null or not exists (
       select 1 from public.members m
        where lower(m.email) = lower(auth.email()) and m.department_id = v_my_dept
          and m.access && array['Board Member', 'Department Admin', 'Officer']::text[]) then
    raise exception 'Only leaders can share a fundraiser with the station';
  end if;
  update public.fundraisers set shared_with_station = p_shared
   where id = p_fundraiser_id and department_id = v_my_dept;
  if not found then raise exception 'Not in your department'; end if;
  return p_shared;
end;
$function$

set_fundraiser_step_visible(uuid,boolean.def:
CREATE OR REPLACE FUNCTION public.set_fundraiser_step_visible(p_item_id uuid, p_visible boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- B4C:station_fundraiser — department-scoped leader write of action_items.station_visible ONLY.
declare
  v_my_dept uuid := public.my_department_id();
begin
  if p_visible is null then raise exception 'Choose shown or hidden'; end if;
  if v_my_dept is null or not exists (
       select 1 from public.members m
        where lower(m.email) = lower(auth.email()) and m.department_id = v_my_dept
          and m.access && array['Board Member', 'Department Admin', 'Officer']::text[]) then
    raise exception 'Only leaders can choose what the station sees';
  end if;
  update public.action_items ai set station_visible = p_visible
   where ai.id = p_item_id and ai.department_id = v_my_dept
     and ai.fundraiser_id is not null
     and exists (select 1 from public.fundraisers f where f.id = ai.fundraiser_id and f.department_id = v_my_dept);
  if not found then raise exception 'Not a planning step of your department''s fundraiser'; end if;
  return p_visible;
end;
$function$
